#include <iostream>
#include <memory>
#include <string>
#include <unordered_map>

struct Texture
{
    std::string name{};
    explicit Texture(std::string n) : name{std::move(n)} { std::cout << "load " << name << '\n'; }
    ~Texture() { std::cout << "free " << name << '\n'; }
};

class Cache
{
public:
    std::shared_ptr<Texture> get(const std::string& name) { return std::make_shared<Texture>(name); }

private:
    std::unordered_map<std::string, std::weak_ptr<Texture>> m_items{};
};

int main()
{
    Cache cache{};
    auto a{cache.get("grass")};
}
